### C# Enterprise Ledger Source Code

You can copy and run this entire file directly in a .NET 6/7/8 Console Project.

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

namespace EnterpriseLedger
{
    #region Core Cryptographic & Serialization Utilities

    public static class CryptoUtils
    {
        /// <summary>
        /// Generates a secure ECDSA (NistP256) Key Pair represented as Hex strings.
        /// </summary>
        public static (string PrivateKey, string PublicKey) GenerateKeyPair()
        {
            using var ecdsa = ECDsa.Create(ECCurve.NamedCurves.nistP256);
            var privateKey = Convert.ToHexString(ecdsa.ExportECPrivateKey());
            var publicKey = Convert.ToHexString(ecdsa.ExportSubjectPublicKeyInfo());
            return (privateKey, publicKey);
        }

        /// <summary>
        /// Signs raw binary data using an ECDSA Private Key.
        /// </summary>
        public static byte[] SignData(string privateKeyHex, byte[] data)
        {
            using var ecdsa = ECDsa.Create();
            ecdsa.ImportECPrivateKey(Convert.FromHexString(privateKeyHex), out _);
            return ecdsa.SignData(data, HashAlgorithmName.SHA256);
        }

        /// <summary>
        /// Verifies a signature against the original data using an ECDSA Public Key.
        /// </summary>
        public static bool VerifySignature(string publicKeyHex, byte[] data, byte[] signature)
        {
            try
            {
                using var ecdsa = ECDsa.Create();
                ecdsa.ImportSubjectPublicKeyInfo(Convert.FromHexString(publicKeyHex), out _);
                return ecdsa.VerifyData(data, signature, HashAlgorithmName.SHA256);
            }
            catch
            {
                return false;
            }
        }
    }

    public static class MerkleUtils
    {
        /// <summary>
        /// Calculates the Merkle Root hash of a set of transactions.
        /// </summary>
        public static string ComputeMerkleRoot(List<Transaction> transactions)
        {
            if (transactions == null || transactions.Count == 0)
                return Convert.ToHexString(SHA256.HashData(Array.Empty<byte>()));

            var leafHashes = transactions.Select(tx => tx.Id).ToList();
            while (leafHashes.Count > 1)
            {
                if (leafHashes.Count % 2 != 0)
                {
                    leafHashes.Add(leafHashes[^1]); // Duplicate the last item if odd
                }

                var internalHashes = new List<string>();
                for (int i = 0; i < leafHashes.Count; i += 2)
                {
                    var combined = leafHashes[i] + leafHashes[i + 1];
                    var combinedHash = SHA256.HashData(Encoding.UTF8.GetBytes(combined));
                    internalHashes.Add(Convert.ToHexString(combinedHash));
                }
                leafHashes = internalHashes;
            }

            return leafHashes[0];
        }
    }

    public static class TransactionHasher
    {
        /// <summary>
        /// Deterministically serializes and hashes transaction properties (excluding signature inputs).
        /// </summary>
        public static byte[] ComputeTxContentHash(Transaction tx)
        {
            using var ms = new MemoryStream();
            using var bw = new BinaryWriter(ms, Encoding.UTF8);

            bw.Write(tx.Timestamp);
            bw.Write(tx.Inputs.Count);
            foreach (var input in tx.Inputs)
            {
                bw.Write(input.TransactionId);
                bw.Write(input.OutputIndex);
            }

            bw.Write(tx.Outputs.Count);
            foreach (var output in tx.Outputs)
            {
                bw.Write(output.RecipientPublicKey);
                bw.Write(output.Amount);
                bw.Write(output.Index);
            }

            bw.Flush();
            return SHA256.HashData(ms.ToArray());
        }
    }

    #endregion

    #region Data Domain Models

    public record UtxoKey(string TransactionId, int OutputIndex);

    public class TransactionOutput
    {
        public string RecipientPublicKey { get; init; }
        public decimal Amount { get; init; }
        public int Index { get; init; }

        public TransactionOutput(string recipientPublicKey, decimal amount, int index)
        {
            RecipientPublicKey = recipientPublicKey;
            Amount = amount;
            Index = index;
        }
    }

    public class TransactionInput
    {
        public string TransactionId { get; init; }
        public int OutputIndex { get; init; }
        public byte[] Signature { get; set; } // Set after signing the TX hash

        public TransactionInput(string transactionId, int outputIndex, byte[] signature = null)
        {
            TransactionId = transactionId;
            OutputIndex = outputIndex;
            Signature = signature;
        }
    }

    public class Transaction
    {
        public string Id { get; set; }
        public List<TransactionInput> Inputs { get; init; } = new();
        public List<TransactionOutput> Outputs { get; init; } = new();
        public long Timestamp { get; init; }

        public bool IsCoinbase => Inputs.Count == 0 && Outputs.Count == 1;

        public Transaction()
        {
            Timestamp = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        }

        public void FinalizeAndHash()
        {
            Id = Convert.ToHexString(TransactionHasher.ComputeTxContentHash(this));
        }
    }

    public class Block
    {
        public int Index { get; init; }
        public string PrevHash { get; init; }
        public string Hash { get; set; }
        public long Timestamp { get; init; }
        public long Nonce { get; set; }
        public int Difficulty { get; init; }
        public string MerkleRoot { get; init; }
        public List<Transaction> Transactions { get; init; } = new();

        public Block(int index, string prevHash, int difficulty, List<Transaction> transactions)
        {
            Index = index;
            PrevHash = prevHash;
            Difficulty = difficulty;
            Transactions = transactions;
            Timestamp = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
            MerkleRoot = MerkleUtils.ComputeMerkleRoot(transactions);
        }

        public string ComputeHash()
        {
            var dataToHash = $"{Index}-{PrevHash}-{Timestamp}-{Nonce}-{Difficulty}-{MerkleRoot}";
            var hashBytes = SHA256.HashData(Encoding.UTF8.GetBytes(dataToHash));
            return Convert.ToHexString(hashBytes);
        }
    }

    #endregion

    #region Module 1: Transaction Pool

    public interface ITransactionPool
    {
        bool AddTransaction(Transaction tx, Dictionary<UtxoKey, TransactionOutput> activeUtxoSet, out string error);
        List<Transaction> GetPendingTransactions();
        void ClearTransactions(IEnumerable<Transaction> txs);
    }

    public class TransactionPool : ITransactionPool
    {
        private readonly object _lock = new();
        private readonly List<Transaction> _pendingTransactions = new();
        private readonly HashSet<UtxoKey> _spentPoolInputs = new();

        public bool AddTransaction(Transaction tx, Dictionary<UtxoKey, TransactionOutput> activeUtxoSet, out string error)
        {
            lock (_lock)
            {
                if (tx.IsCoinbase)
                {
                    error = "Coinbase transactions cannot be submitted manually to the transaction pool.";
                    return false;
                }

                // Verify structural transaction ID
                var calculatedTxId = Convert.ToHexString(TransactionHasher.ComputeTxContentHash(tx));
                if (tx.Id != calculatedTxId)
                {
                    error = "Transaction ID mismatch. Contents modified after signing.";
                    return false;
                }

                decimal inputSum = 0;
                var txHashBytes = TransactionHasher.ComputeTxContentHash(tx);

                // Ensure strict structure
                for (int i = 0; i < tx.Outputs.Count; i++)
                {
                    if (tx.Outputs[i].Index != i)
                    {
                        error = "Malformed transaction output index.";
                        return false;
                    }
                }

                // Validate Inputs
                foreach (var input in tx.Inputs)
                {
                    var inputKey = new UtxoKey(input.TransactionId, input.OutputIndex);

                    // Check pool-level double spending (already reserved in pool memory)
                    if (_spentPoolInputs.Contains(inputKey))
                    {
                        error = $"UTXO reference {input.TransactionId}:{input.OutputIndex} already reserved by another pending transaction.";
                        return false;
                    }

                    // Validate Ledger-level UTXO availability
                    if (!activeUtxoSet.TryGetValue(inputKey, out var unspentOutput))
                    {
                        error = $"Referenced UTXO {input.TransactionId}:{input.OutputIndex} does not exist or has been spent.";
                        return false;
                    }

                    // Cryptographic signature checks
                    if (!CryptoUtils.VerifySignature(unspentOutput.RecipientPublicKey, txHashBytes, input.Signature))
                    {
                        error = "Cryptographic signature validation failed on input.";
                        return false;
                    }

                    inputSum += unspentOutput.Amount;
                }

                decimal outputSum = tx.Outputs.Sum(o => o.Amount);
                if (inputSum < outputSum)
                {
                    error = $"Insufficient funds. Inputs spent: {inputSum}, outputs declared: {outputSum}.";
                    return false;
                }

                // Reserve inputs to prevent double-spending in the pool
                foreach (var input in tx.Inputs)
                {
                    _spentPoolInputs.Add(new UtxoKey(input.TransactionId, input.OutputIndex));
                }

                _pendingTransactions.Add(tx);
                error = null;
                return true;
            }
        }

        public List<Transaction> GetPendingTransactions()
        {
            lock (_lock)
            {
                return _pendingTransactions.ToList();
            }
        }

        public void ClearTransactions(IEnumerable<Transaction> txs)
        {
            lock (_lock)
            {
                foreach (var tx in txs)
                {
                    _pendingTransactions.RemoveAll(t => t.Id == tx.Id);
                    foreach (var input in tx.Inputs)
                    {
                        _spentPoolInputs.Remove(new UtxoKey(input.TransactionId, input.OutputIndex));
                    }
                }
            }
        }
    }

