    #region Module 2: Block Miner

    public interface IBlockMiner
    {
        Block MineBlock(int index, string prevHash, List<Transaction> transactions, int difficulty, CancellationToken cancellationToken = default);
    }

    public class BlockMiner : IBlockMiner
    {
        public Block MineBlock(int index, string prevHash, List<Transaction> transactions, int difficulty, CancellationToken cancellationToken = default)
        {
            var block = new Block(index, prevHash, difficulty, transactions);
            var prefixTarget = new string('0', difficulty);

            while (true)
            {
                cancellationToken.ThrowIfCancellationRequested();

                var calculatedHash = block.ComputeHash();
                if (calculatedHash.StartsWith(prefixTarget))
                {
                    block.Hash = calculatedHash;
                    return block;
                }

                block.Nonce++;
            }
        }
    }

