    /// <summary>
    /// Generates fully functional Cryptographic Self-Signed Root Certificate Authority, Server Certificate
    /// and Client Certificates dynamically in-memory without needing local storage dependencies.
    /// </summary>
    public static class CertificateAuthorityGenerator
    {
        public static (X509Certificate2 Ca, X509Certificate2 Server, X509Certificate2 Client) GenerateCertificates()
        {
            // 1. Generate Root CA Authority
            using var caRsa = RSA.Create(2048);
            var caRequest = new CertificateRequest("CN=MockMeshRootAuthority", caRsa, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);
            caRequest.CertificateExtensions.Add(new X509BasicConstraintsExtension(true, true, 0, true));
            caRequest.CertificateExtensions.Add(new X509KeyUsageExtension(X509KeyUsageFlags.KeyCertSign | X509KeyUsageFlags.CrlSign, true));

            var caCert = caRequest.CreateSelfSigned(DateTimeOffset.UtcNow.AddMinutes(-10), DateTimeOffset.UtcNow.AddYears(1));
            var caCertWithKey = caCert.CopyWithPrivateKey(caRsa);

            // 2. Generate Server Certificate
            using var serverRsa = RSA.Create(2048);
            var serverRequest = new CertificateRequest("CN=localhost", serverRsa, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);
            serverRequest.CertificateExtensions.Add(new X509BasicConstraintsExtension(false, false, 0, false));
            serverRequest.CertificateExtensions.Add(new X509KeyUsageExtension(X509KeyUsageFlags.DigitalSignature | X509KeyUsageFlags.KeyEncipherment, true));
            serverRequest.CertificateExtensions.Add(new X509EnhancedKeyUsageExtension(new OidCollection { new Oid("1.3.6.1.5.5.7.3.1") }, false)); // Server Auth

            var sanBuilder = new SubjectAlternativeNameBuilder();
            sanBuilder.AddIpAddress(IPAddress.Loopback);
            sanBuilder.AddDnsName("localhost");
            serverRequest.CertificateExtensions.Add(sanBuilder.Build());

            byte[] serial = new byte[8];
            RandomNumberGenerator.Fill(serial);
            using var serverCert = serverRequest.Create(caCertWithKey, DateTimeOffset.UtcNow.AddMinutes(-5), DateTimeOffset.UtcNow.AddDays(30), serial);
            var serverCertWithKey = serverCert.CopyWithPrivateKey(serverRsa);

            // 3. Generate Client Certificate
            using var clientRsa = RSA.Create(2048);
            var clientRequest = new CertificateRequest("CN=SidecarInboundClient", clientRsa, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);
            clientRequest.CertificateExtensions.Add(new X509BasicConstraintsExtension(false, false, 0, false));
            clientRequest.CertificateExtensions.Add(new X509KeyUsageExtension(X509KeyUsageFlags.DigitalSignature, true));
            clientRequest.CertificateExtensions.Add(new X509EnhancedKeyUsageExtension(new OidCollection { new Oid("1.3.6.1.5.5.7.3.2") }, false)); // Client Auth

            byte[] clientSerial = new byte[8];
            RandomNumberGenerator.Fill(clientSerial);
            using var clientCert = clientRequest.Create(caCertWithKey, DateTimeOffset.UtcNow.AddMinutes(-5), DateTimeOffset.UtcNow.AddDays(30), clientSerial);
            var clientCertWithKey = clientCert.CopyWithPrivateKey(clientRsa);

            // Export to secure PKCS12 bytecode standard to seamlessly run in-memory across Linux, macOS, and Windows
            return (
                new X509Certificate2(caCertWithKey.Export(X509ContentType.Pkcs12)),
                new X509Certificate2(serverCertWithKey.Export(X509ContentType.Pkcs12)),
                new X509Certificate2(clientCertWithKey.Export(X509ContentType.Pkcs12))
            );
        }
    }

